// ===== BROWSER RESEARCH - TikTok =====
// Scrapes TikTok search results for niche content

const niche = $input.first().json.niche;

// TikTok search URL
const searchUrl = `https://www.tiktok.com/search?q=${encodeURIComponent(niche)}`;

// Return the URL for Playwright to process
return [{
  json: {
    platform: 'tiktok',
    url: searchUrl,
    niche: niche,
    tasks: [
      'Scroll feed and collect top 50 video titles',
      'Extract view counts from visible videos',
      'Note content formats (talking head, text overlay, etc)',
      'Collect hashtags used',
      'Identify common hooks in first 3 seconds',
      'Note music/audio trends',
      'Collect comment themes from top videos'
    ]
  }
}];

// ===== BROWSER RESEARCH - Instagram =====

const niche = $input.first().json.niche;

const hashtagUrl = `https://www.instagram.com/explore/tags/${encodeURIComponent(niche.replace(/\s+/g, ''))}/`;
const searchUrl = `https://www.instagram.com/explore/search/keyword/?q=${encodeURIComponent(niche)}`;

return [{
  json: {
    platform: 'instagram',
    urls: [hashtagUrl, searchUrl],
    niche: niche,
    tasks: [
      'Find top performing carousel posts in niche',
      'Extract carousel design styles and layouts',
      'Collect caption formats and lengths',
      'Note hashtag sets used (first 30)',
      'Identify CTA patterns (link in bio, comment below, etc)',
      'Analyze color schemes and typography',
      'Collect engagement metrics (likes, comments, saves)',
      'Note posting frequency of top accounts',
      'Identify content pillars (educate, entertain, inspire, sell)',
      'Read comments for pain points and questions'
    ]
  }
}];

// ===== BROWSER RESEARCH - Reddit =====

const niche = $input.first().json.niche;

return [{
  json: {
    platform: 'reddit',
    url: `https://www.reddit.com/search/?q=${encodeURIComponent(niche)}&sort=top&t=month`,
    niche: niche,
    tasks: [
      'Find subreddits related to niche',
      'Extract top posts and their engagement',
      'Read comment threads for pain points',
      'Identify common questions asked',
      'Note language/terminology used',
      'Find controversial topics (high comment count)',
      'Collect trending discussions',
      'Identify what content gets upvoted vs downvoted'
    ]
  }
}];

// ===== BROWSER RESEARCH - YouTube =====

const niche = $input.first().json.niche;

return [{
  json: {
    platform: 'youtube',
    url: `https://www.youtube.com/results?search_query=${encodeURIComponent(niche + ' best content')}`,
    niche: niche,
    tasks: [
      'Find top performing videos in niche',
      'Extract thumbnail styles and patterns',
      'Analyze title hooks (curiosity gap, numbers, etc)',
      'Note video lengths that perform best',
      'Collect view counts and like ratios',
      'Read top comments for audience insights',
      'Identify content formats that work',
      'Note posting frequency of top channels'
    ]
  }
}];

// ===== BROWSER RESEARCH - Pinterest =====

const niche = $input.first().json.niche;

return [{
  json: {
    platform: 'pinterest',
    url: `https://www.pinterest.com/search/pins/?q=${encodeURIComponent(niche)}`,
    niche: niche,
    tasks: [
      'Find top performing pins in niche',
      'Extract pin design styles',
      'Note color palettes that perform',
      'Collect pin descriptions and keywords',
      'Identify board themes',
      'Note text overlay styles',
      'Find trending pin formats'
    ]
  }
}];

// ===== KNOWLEDGE BASE AGGREGATOR =====
// Combines all research data into unified knowledge base

const staticData = $getWorkflowStaticData('global');
const allData = $input.all();

// Initialize knowledge base
if (!staticData.knowledgeBase) {
  staticData.knowledgeBase = {
    // Hooks & Content
    topHooks: [],
    viralHooks: [],
    hookPatterns: [],
    contentIdeas: [],
    contentFormats: [],
    contentPillars: [],

    // Captions & CTAs
    captionTemplates: [],
    topCTAs: [],
    ctaPatterns: [],

    // Hashtags
    topHashtags: [],
    hashtagSets: [],
    trendingHashtags: [],

    // Psychology & Audience
    painPoints: [],
    desires: [],
    questions: [],
    objections: [],
    emotionalTriggers: [],
    audienceLanguage: [],
    audiencePersonas: [],

    // Trends
    trendingTopics: [],
    trendingAudio: [],
    trendingFormats: [],
    trendHistory: [],

    // Competitors
    competitors: [],
    competitorStrategies: [],
    competitorWeaknesses: [],

    // Design & Style
    designStyles: [],
    colorPalettes: [],
    typographyStyles: [],
    carouselLayouts: [],

    // Timing & Algorithm
    bestTimes: [],
    bestDays: [],
    postingFrequency: null,
    algorithmInsights: [],

    // Monetization
    products: [],
    monetizationStrategies: [],
    affiliateOpportunities: [],

    // Performance
    viralPatterns: [],
    flopPatterns: [],
    engagementDrivers: [],

    // Meta
    lastUpdated: new Date().toISOString(),
    totalDataPoints: 0,
    sources: []
  };
}

const kb = staticData.knowledgeBase;

// Process each research source
for (const item of allData) {
  const data = item.json;

  if (data.platform === 'tiktok') {
    // Extract TikTok insights
    if (data.hooks) kb.topHooks.push(...data.hooks);
    if (data.hashtags) kb.topHashtags.push(...data.hashtags);
    if (data.trends) kb.trendingTopics.push(...data.trends);
    if (data.contentFormats) kb.contentFormats.push(...data.contentFormats);
    kb.sources.push('tiktok');
  }

  if (data.platform === 'instagram') {
    if (data.captions) kb.captionTemplates.push(...data.captions);
    if (data.ctas) kb.topCTAs.push(...data.ctas);
    if (data.hashtags) kb.hashtagSets.push(...data.hashtags);
    if (data.designStyles) kb.designStyles.push(...data.designStyles);
    if (data.colorPalettes) kb.colorPalettes.push(...data.colorPalettes);
    if (data.competitors) kb.competitors.push(...data.competitors);
    if (data.painPoints) kb.painPoints.push(...data.painPoints);
    kb.sources.push('instagram');
  }

  if (data.platform === 'reddit') {
    if (data.questions) kb.questions.push(...data.questions);
    if (data.painPoints) kb.painPoints.push(...data.painPoints);
    if (data.language) kb.audienceLanguage.push(...data.language);
    if (data.discussions) kb.contentIdeas.push(...data.discussions);
    kb.sources.push('reddit');
  }

  if (data.platform === 'youtube') {
    if (data.hooks) kb.viralHooks.push(...data.hooks);
    if (data.thumbnailStyles) kb.designStyles.push(...data.thumbnailStyles);
    if (data.titlePatterns) kb.hookPatterns.push(...data.titlePatterns);
    if (data.comments) kb.questions.push(...data.comments);
    kb.sources.push('youtube');
  }

  if (data.platform === 'pinterest') {
    if (data.pinStyles) kb.designStyles.push(...data.pinStyles);
    if (data.colorPalettes) kb.colorPalettes.push(...data.colorPalettes);
    if (data.keywords) kb.topHashtags.push(...data.keywords);
    kb.sources.push('pinterest');
  }
}

// Deduplicate all arrays
for (const key of Object.keys(kb)) {
  if (Array.isArray(kb[key])) {
    kb[key] = [...new Set(kb[key])];
  }
}

// Update meta
kb.lastUpdated = new Date().toISOString();
kb.totalDataPoints = Object.values(kb).reduce((sum, val) => {
  return sum + (Array.isArray(val) ? val.length : 0);
}, 0);

// Generate AI analysis prompt
const analysisPrompt = `Based on the following knowledge base data for the niche "${data.niche}", generate:

1. TOP 10 VIRAL HOOKS that work in this niche
2. TOP 20 HASHTAG SETS (grouped by category)
3. BEST POSTING TIMES for this niche
4. TOP 5 CTAs that drive engagement
5. AUDIENCE PAIN POINTS (top 10)
6. CONTENT IDEAS (20 unique angles)
7. COMPETITOR ANALYSIS (what they do well, gaps)
8. DESIGN RECOMMENDATIONS (colors, fonts, layouts)
9. MONETIZATION STRATEGIES (top 5)
10. A/B TEST SUGGESTIONS

Knowledge Base Data:
${JSON.stringify(kb, null, 2)}

Return as structured JSON.`;

return [{
  json: {
    knowledgeBase: kb,
    analysisPrompt,
    niche: data.niche,
    chatId: data.chatId
  }
}];

