// ===== MERGE AI INSIGHTS INTO KNOWLEDGE BASE =====

const kb = $input.first().json.knowledgeBase;
const aiResponse = $input.last().json;

try {
  const insights = JSON.parse(aiResponse.choices[0].message.content);

  // Merge AI-generated insights
  if (insights.topHooks) kb.topHooks = [...new Set([...insights.topHooks, ...kb.topHooks])];
  if (insights.hashtagSets) kb.hashtagSets = [...new Set([...insights.hashtagSets, ...kb.hashtagSets])];
  if (insights.bestTimes) kb.bestTimes = [...new Set([...insights.bestTimes, ...kb.bestTimes])];
  if (insights.topCTAs) kb.topCTAs = [...new Set([...insights.topCTAs, ...kb.topCTAs])];
  if (insights.painPoints) kb.painPoints = [...new Set([...insights.painPoints, ...kb.painPoints])];
  if (insights.contentIdeas) kb.contentIdeas = [...new Set([...insights.contentIdeas, ...kb.contentIdeas])];
  if (insights.competitorAnalysis) kb.competitorStrategies = insights.competitorAnalysis;
  if (insights.designRecommendations) kb.designStyles = [...new Set([...insights.designRecommendations, ...kb.designStyles])];
  if (insights.monetizationStrategies) kb.monetizationStrategies = insights.monetizationStrategies;
  if (insights.abTestSuggestions) kb.abTests = insights.abTestSuggestions;
  if (insights.audiencePersonas) kb.audiencePersonas = insights.audiencePersonas;
  if (insights.viralPatterns) kb.viralPatterns = [...new Set([...insights.viralPatterns, ...kb.viralPatterns])];
  if (insights.hookPatterns) kb.hookPatterns = [...new Set([...insights.hookPatterns, ...kb.hookPatterns])];
} catch (e) {
  // AI response parsing failed, keep raw data
  kb.aiRawResponse = aiResponse.choices[0].message.content;
}

kb.lastUpdated = new Date().toISOString();
kb.totalDataPoints = Object.values(kb).reduce((sum, val) => {
  return sum + (Array.isArray(val) ? val.length : 0);
}, 0);

// Save to NocoDB
const niche = $input.first().json.niche;
const chatId = $input.first().json.chatId;

return [{
  json: {
    knowledgeBase: kb,
    niche,
    chatId,
    saveToNocoDB: true,
    notifyUser: true
  }
}];

